INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1000, 190801, "様々なミニゲームをご用意してい\nますよ！\nどのミニゲームで遊びますか？", 1000001, "2020-02-15 15:00:00", 13, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1000, 190801, "楽しいミニゲームをご紹介！\nあなたはどのミニゲームで\n遊びますか？", 1000002, "2020-02-15 15:00:00", 13, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1001, 190801, "こちらは{0}ルピで\n販売中！\nぜひ購入して\n遊んでくださいね！", 1001001, "2020-02-15 15:00:00", 13, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1002, 190801, "動くハートに合わせてタップ！\nシズルさんとエリコさんの\nチョコレートケーキ作りを\nお手伝いしましょう！", 1002001, "2020-02-15 15:00:00", 12, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1003, 190801, "クウカさんを引っ張ってより遠く\nへ飛ばしてあげましょう！\n色々なハプニングでクウカさんに\nエクスタシーを届けましょう！", 1003001, "2020-02-15 15:00:00", 11, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1004, 190801, "左右をタップしてマジムンを倒し\nましょう！\n放て！\n琉球犬アラウンドシュート！", 1004001, "2020-02-15 15:00:00", 3, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1005, 190801, "パネルをタップしてドラゴンズ\nネストのみなさんと一緒に\nしりとり対決をしませんか？\nおしりに「ん」はご法度です。", 1005001, "2020-02-15 15:00:00", 7, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1006, 190801, "素早い動きのネズミに合わせ、\nタップで撃退！\nやる気のリンさんと一緒に\n大切なチーズを守りましょう！", 1006001, "2020-05-31 12:00:00", 2, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1007, 190801, "ミサトさんや部員のみなさんと\nバッティングの特訓ですよ！\nホームランを目指して、ボールを\nタイミングよく打ち返しましょう", 1007001, "2020-08-15 15:00:00", 4, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1008, 190801, "カルミナメダルを使って、\n応援グッズをゲットしましょう！\nメダルはルピを使って\n交換できますよ。\n", 1008001, "2021-08-31 12:00:00", 6, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1009, 190801, "食べたプリンはプリンノート\nで確認してみましょう！\nプリンの材料はルピを使って\n購入できますよ。", 1009001, "2021-12-18 15:00:00", 13, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1010, 190801, "チームでクイズに挑みましょう！\nソロで自分の実力を試すか、マル\nチで仲間と一緒に遊ぶか、好きな\nモードを選んでくださいね♪", 1010001, "2022-02-15 15:00:00", 4, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1011, 190801, "３つのラウンドを駆け抜け、\n総合１位を目指しましょう！\n参加者の皆さんの特徴や、\nＧＰの特徴にも注目です♪", 1011001, "2022-07-18 15:00:00", 6, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1012, 190801, "キャルさん、スズナさんと一緒に\nクイズでお勉強しましょう！\n放課後の教室で二人きりって…\nなんだかドキドキしますね♪", 1012001, "2023-09-18 15:00:00", 6, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1013, 190801, "魔物の討伐任務にいざ行軍！\nエリコさん、マコトさんの\n頼もしい背中は、\n新兵さんたちの憧れですね♪", 1013001, "2024-04-18 15:00:00", 6, "2030-04-01 14:00:00", 0);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1014, 190801, "バンディ・シスターズのみなさん\nと戦車バトルに挑戦です！\nパーツやメンバーの組み合わせで\nマシンの特徴が変化しますよ♪", 1014001, "2024-11-18 15:00:00", 6, "2030-04-01 14:00:00", 0);
